mkdir -p /workspace/tmp && cat > /workspace/tmp/harness.py <<'PYEOF'
import json, subprocess, sys
BRIDGE = '/workspace/submission/bridge.py'

def run(scenario):
    p = subprocess.run([sys.executable, BRIDGE], input=json.dumps(scenario).encode(),
                       stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=60)
    if p.returncode:
        raise SystemExit('CRASH %r\n%s' % (scenario, p.stderr.decode()[-3000:]))
    return json.loads(p.stdout)

def hdr(sid=0, *pairs):
    return {"sid": sid, "type": "headers", "fields": [list(p) for p in pairs]}

def data(sid=0, hexstr=''):
    return {"sid": sid, "type": "data", "hex": hexstr}

def unk(sid=0, ft=33, hexstr='aa'):
    return {"sid": sid, "type": "unknown", "frame_type": ft, "hex": hexstr}

def fin(sid=0):
    return {"sid": sid, "type": "fin"}

def reset(sid=0):
    return {"sid": sid, "type": "reset"}

def base_headers(**kw):
    m = kw.get('method', 'GET'); s = kw.get('scheme', 'https')
    a = kw.get('authority', 'demo.test'); p = kw.get('path', '/')
    pairs = [[":method", m], [":scheme", s]]
    if a is not None:
        pairs.append([":authority", a])
    pairs.append([":path", p])
    for extra in kw.get('extra', []):
        pairs.append(list(extra))
    return pairs

def scen(routes=None, events=None):
    if routes is None:
        routes = {"https://demo.test": "rack-a", "http://demo.test": "rack-a",
                  "https://alt.test:8443": "rack-b", "http://[2001:db8::1]:8080": "rack-c",
                  "https://unused.test": "rack-z"}
    return {"routes": routes, "events": events or []}

def stream_result(result, sid):
    for rec in result['streams']:
        if rec['sid'] == sid:
            return rec
    raise AssertionError('missing sid %r in %r' % (sid, result))

def body_hex(result, origin):
    return result['origins'][origin]

def raw(result, origin):
    return bytes.fromhex(result['origins'][origin])
